[InitializeOnLoad]public static class BeachDetailsCheck{static BeachDetailsCheck(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachDetailsCheck.request"))return;File.Delete("BeachDetailsCheck.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=s.GetRootGameObjects().Single(g=>g.name=="South Coast Beach Details");var yard=s.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var bounds=yard.GetComponent<Renderer>().bounds;bounds.Expand(new Vector3(35,40,35));int overlap=root.transform.Cast<Transform>().SelectMany(t=>t.Cast<Transform>()).Count(t=>bounds.Contains(t.position));var mats=root.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().ToArray();int errors=mats.Sum(m=>ShaderUtil.GetShaderMessages(m.shader).Count(e=>e.severity.ToString()=="Error"));var rock=root.GetComponentsInChildren<MeshFilter>().First(f=>f.name.ToLower().Contains("granite"));var p=rock.GetComponent<Renderer>().bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,p+new Vector3(-17,10,-20),p+Vector3.up*2,"Beach-Granite-Rocks-Closeup"});File.AppendAllText("FinalEnvironmentRoadReview/SouthCoastBeachDetails.txt","\nCHECK port buffer overlaps="+overlap+"; shader errors="+errors+"; decorative colliders="+root.GetComponentsInChildren<Collider>().Length+"; shared materials="+mats.Length);}}

